using DcSharp.Core.Dreamcast.Memory;

namespace DcSharp.Core.Cpu;

public sealed class Sh4Cpu
{
    private readonly DreamcastMemory memory;
    private readonly Sh4TrapHandler? trapHandler;
    private uint? delayedBranchTarget;
    private uint? immediateBranchTarget;

    public Sh4Cpu(DreamcastMemory memory, uint entryPoint, Sh4TrapHandler? trapHandler = null)
    {
        this.memory = memory;
        this.trapHandler = trapHandler;
        State.Pc = entryPoint;
    }

    public Sh4State State { get; } = new();

    private void WriteUInt32AsInstruction(uint pc, uint address, uint value)
    {
        var previousPc = memory.CurrentInstructionPc;
        var previousOpcode = memory.CurrentInstructionOpcode;
        try
        {
            memory.CurrentInstructionPc = pc;
            memory.CurrentInstructionOpcode = memory.ReadInstructionUInt16(pc);
            memory.WriteUInt32(address, value);
        }
        finally
        {
            memory.CurrentInstructionPc = previousPc;
            memory.CurrentInstructionOpcode = previousOpcode;
        }
    }

    public Sh4StepResult Step()
    {
        var pc = State.Pc;
        memory.CurrentInstructionPc = pc;
        memory.CurrentInstructionOpcode = null;
        if (delayedBranchTarget is null && TryAcceptExternalInterrupt(pc, out var interruptTrace))
        {
            State.InstructionsExecuted++;
            return new Sh4StepResult(pc, 0, interruptTrace, State.InstructionsExecuted);
        }

        if (trapHandler?.Invoke(State, memory, out var trapTrace) == true)
        {
            State.InstructionsExecuted++;
            return new Sh4StepResult(pc, 0, trapTrace, State.InstructionsExecuted);
        }

        var opcode = memory.ReadInstructionUInt16(pc);
        memory.CurrentInstructionOpcode = opcode;
        var trace = Execute(pc, opcode);
        State.InstructionsExecuted++;

        return new Sh4StepResult(pc, opcode, trace, State.InstructionsExecuted);
    }

    internal bool TryFastForwardCountedIdleLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if ((State.Sr & Sh4State.SrBlockBit) == 0 && ((State.Sr >> 4) & 0xF) != 0xF)
        {
            return false;
        }

        if ((step.Opcode & 0xFF00) != 0x8F00 || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal))
        {
            return false;
        }

        var branchTarget = (uint)(step.Pc + 4 + ((sbyte)(step.Opcode & 0xFF) * 2));
        if (delayedBranchTarget != branchTarget || State.Pc != step.Pc + 2 || branchTarget >= step.Pc)
        {
            return false;
        }

        var byteDistance = step.Pc - branchTarget;
        if ((byteDistance & 1) != 0)
        {
            return false;
        }

        var dtPc = step.Pc - 2;
        var dtOpcode = memory.ReadInstructionUInt16(dtPc);
        if ((dtOpcode & 0xF0FF) != 0x4010)
        {
            return false;
        }

        for (var pc = branchTarget; pc < dtPc; pc += 2)
        {
            if (memory.ReadInstructionUInt16(pc) != 0x0009)
            {
                return false;
            }
        }

        var counterRegister = (dtOpcode >> 8) & 0xF;
        var remainingIterations = State.R[counterRegister];
        if (remainingIterations == 0)
        {
            return false;
        }

        var bodyInstructionCount = byteDistance / 2;
        if (!TryComputeSkippedInstructions(remainingIterations, bodyInstructionCount, out skippedInstructions)
            || skippedInstructions > maxInstructionsToSkip)
        {
            skippedInstructions = 0;
            return false;
        }

        var delaySlotOpcode = memory.ReadInstructionUInt16(step.Pc + 2);
        if (!TryApplyRepeatedDelaySlot(delaySlotOpcode, (ulong)remainingIterations + 1))
        {
            skippedInstructions = 0;
            return false;
        }

        State.R[counterRegister] = 0;
        State.T = true;
        State.Pc = step.Pc + 4;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardImmediateDtLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if ((step.Opcode & 0xFF00) is not (0x8900 or 0x8B00) || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal))
        {
            return false;
        }

        var branchTarget = (uint)(step.Pc + 4 + ((sbyte)(step.Opcode & 0xFF) * 2));
        if (State.Pc != branchTarget || branchTarget + 2 != step.Pc)
        {
            return false;
        }

        var dtOpcode = memory.ReadInstructionUInt16(branchTarget);
        if ((dtOpcode & 0xF0FF) != 0x4010)
        {
            return false;
        }

        var counterRegister = (dtOpcode >> 8) & 0xF;
        var remainingIterations = State.R[counterRegister];
        if (remainingIterations == 0 || maxInstructionsToSkip < 2)
        {
            return false;
        }

        var iterationsToSkip = Math.Min((ulong)remainingIterations, maxInstructionsToSkip / 2);
        if (iterationsToSkip == 0)
        {
            return false;
        }

        skippedInstructions = iterationsToSkip * 2;
        State.R[counterRegister] -= (uint)iterationsToSkip;
        if (iterationsToSkip == remainingIterations)
        {
            State.T = true;
            State.Pc = step.Pc + 2;
        }
        else
        {
            State.T = false;
            State.Pc = branchTarget;
        }

        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinPatternFillLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_8F4E || step.Opcode != 0x8BC9 || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal))
        {
            return false;
        }

        if (delayedBranchTarget is not null || State.Pc != 0x8C00_8EE4)
        {
            return false;
        }

        var stack = State.R[15];
        if (stack is < 0x7E00_0000 or >= 0x7E00_1000)
        {
            return false;
        }

        var column = memory.ReadUInt16(stack + 0x02);
        var row = memory.ReadUInt32(stack + 0x0C);
        var rowLimit = memory.ReadUInt32(stack + 0x04);
        var total = memory.ReadUInt32(stack + 0x10);
        var geometry = memory.ReadUInt32(stack + 0x2C);
        var width = memory.ReadUInt16(stack + 0x24);
        if (rowLimit == 0 || width == 0 || column >= width || row >= rowLimit || total >= 0x0010_0000)
        {
            return false;
        }

        var rowsRemaining = rowLimit - row;
        var firstRowCells = (uint)(width - column);
        var cellsRemaining = firstRowCells + ((rowsRemaining - 1) * (uint)width);
        if (cellsRemaining == 0)
        {
            return false;
        }

        var iterationsToSkip = (ulong)(cellsRemaining - 1);
        const ulong instructionsPerIteration = 59;
        if (iterationsToSkip > ulong.MaxValue / instructionsPerIteration)
        {
            return false;
        }

        skippedInstructions = iterationsToSkip * instructionsPerIteration;
        if (skippedInstructions == 0 || skippedInstructions > maxInstructionsToSkip)
        {
            skippedInstructions = 0;
            return false;
        }

        var finalTotal = (ulong)total + iterationsToSkip;
        if (finalTotal > uint.MaxValue)
        {
            skippedInstructions = 0;
            return false;
        }

        memory.WriteUInt16(stack + 0x02, (ushort)(width - 1));
        memory.WriteUInt32(stack + 0x0C, rowLimit - 1);
        memory.WriteUInt32(stack + 0x10, (uint)finalTotal);
        State.R[0] = (uint)width - 1;
        State.R[1] = rowLimit - 2;
        State.R[2] = rowLimit - 1;
        State.R[3] = rowLimit - 1;
        State.R[4] = (geometry & 0xFFFF) + ((uint)width - 1);
        State.T = false;
        State.Pc = 0x8C00_8F50;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinPatternFillLoopEntryTail(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_8EE4
            || step.Opcode != 0x85F1
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null
            || State.Pc != 0x8C00_8EE6
            || !IsIpBinPatternFillLoop())
        {
            return false;
        }

        var stack = State.R[15];
        if (stack is < 0x7E00_0000 or >= 0x7E00_1000)
        {
            return false;
        }

        var column = memory.ReadUInt16(stack + 0x02);
        var row = memory.ReadUInt32(stack + 0x0C);
        var rowLimit = memory.ReadUInt32(stack + 0x04);
        var total = memory.ReadUInt32(stack + 0x10);
        var geometry = memory.ReadUInt32(stack + 0x2C);
        var width = memory.ReadUInt16(stack + 0x24);
        if (rowLimit == 0 || width == 0 || column >= width || row >= rowLimit || total >= 0x0010_0000)
        {
            return false;
        }

        var rowsRemaining = rowLimit - row;
        var firstRowCells = (uint)(width - column);
        var cellsRemaining = firstRowCells + ((rowsRemaining - 1) * (uint)width);
        if (cellsRemaining == 0)
        {
            return false;
        }

        const ulong instructionsPerIteration = 59;
        var iterationsToSkip = (ulong)cellsRemaining;
        if (iterationsToSkip > ulong.MaxValue / instructionsPerIteration)
        {
            return false;
        }

        skippedInstructions = (iterationsToSkip * instructionsPerIteration) - 1;
        if (skippedInstructions == 0 || skippedInstructions > maxInstructionsToSkip)
        {
            skippedInstructions = 0;
            return false;
        }

        var finalTotal = (ulong)total + iterationsToSkip;
        if (finalTotal > uint.MaxValue)
        {
            skippedInstructions = 0;
            return false;
        }

        memory.WriteUInt16(stack + 0x02, (ushort)(width - 1));
        memory.WriteUInt32(stack + 0x0C, rowLimit - 1);
        memory.WriteUInt32(stack + 0x10, (uint)finalTotal);
        State.R[0] = (uint)width - 1;
        State.R[1] = rowLimit - 2;
        State.R[2] = rowLimit - 1;
        State.R[3] = rowLimit - 1;
        State.R[4] = (geometry & 0xFFFF) + ((uint)width - 1);
        State.T = false;
        State.Pc = 0x8C00_8F50;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinFramebufferCopyLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_834E || step.Opcode != 0x8BFB || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal))
        {
            return false;
        }

        if (delayedBranchTarget is not null || State.Pc != 0x8C00_8348)
        {
            return false;
        }

        var remainingIterations = State.R[7];
        if (remainingIterations == 0)
        {
            return false;
        }

        const ulong instructionsPerIteration = 4;
        var iterationsToSkip = Math.Min((ulong)remainingIterations, maxInstructionsToSkip / instructionsPerIteration);
        if (iterationsToSkip == 0)
        {
            return false;
        }

        skippedInstructions = iterationsToSkip * instructionsPerIteration;
        State.R[4] += (uint)iterationsToSkip * 4;
        State.R[1] -= (uint)iterationsToSkip * 4;
        State.R[7] -= (uint)iterationsToSkip;
        State.T = State.R[7] == 0;
        State.Pc = State.T ? 0x8C00_8350 : 0x8C00_8348;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinShortDelayLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_84FC || step.Opcode != 0x8BF8 || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal))
        {
            return false;
        }

        if (delayedBranchTarget is not null || State.Pc != 0x8C00_84F0)
        {
            return false;
        }

        var stack = State.R[15];
        if (stack is < 0x7E00_0000 or >= 0x7E00_1000)
        {
            return false;
        }

        var counterAddress = stack + 0x08;
        var counter = memory.ReadUInt32(counterAddress);
        var limit = (uint)memory.ReadUInt16(0x8C00_8530);
        if (limit == 0 || counter >= limit)
        {
            return false;
        }

        const ulong instructionsPerIteration = 7;
        var remainingIterations = limit - counter;
        skippedInstructions = remainingIterations * instructionsPerIteration;
        if (skippedInstructions == 0 || skippedInstructions > maxInstructionsToSkip)
        {
            skippedInstructions = 0;
            return false;
        }

        memory.WriteUInt32(counterAddress, limit);
        State.R[1] = limit;
        State.R[2] = limit;
        State.R[3] = limit;
        State.T = true;
        State.Pc = 0x8C00_84FE;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinAsicEventWaitLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_90A0
            || step.Opcode != 0x89FB
            || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal)
            || delayedBranchTarget is not null
            || State.Pc != 0x8C00_909A)
        {
            return false;
        }

        if (memory.ReadInstructionUInt16(0x8C00_909A) != 0xD313
            || memory.ReadInstructionUInt16(0x8C00_909C) != 0x6032
            || memory.ReadInstructionUInt16(0x8C00_909E) != 0xC808
            || memory.ReadInstructionUInt16(0x8C00_90A0) != 0x89FB
            || memory.ReadUInt32(0x8C00_90E8) != 0xA05F_6900)
        {
            return false;
        }

        var asicEvent = memory.ReadUInt32(0xA05F_6900);
        if (State.R[3] != 0xA05F_6900
            || State.R[0] != asicEvent
            || (asicEvent & 0x08) != 0
            || !State.T)
        {
            return false;
        }

        const ulong instructionsPerIteration = 4;
        var iterationsToSkip = maxInstructionsToSkip / instructionsPerIteration;
        if (iterationsToSkip == 0)
        {
            return false;
        }

        skippedInstructions = iterationsToSkip * instructionsPerIteration;
        State.R[3] = 0xA05F_6900;
        State.R[0] = asicEvent;
        State.T = true;
        State.Pc = 0x8C00_909A;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinGlyphTableScanLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_86D8
            || step.Opcode != 0x8BE6
            || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal)
            || delayedBranchTarget is not null
            || immediateBranchTarget != 0x8C00_86A8
            || State.Pc != 0x8C00_86A8
            || !IsIpBinGlyphTableScanLoop())
        {
            return false;
        }

        var stack = State.R[15];
        if (stack is < 0x7E00_0000 or > 0x7E00_0FD0)
        {
            return false;
        }

        var table = memory.ReadUInt32(stack);
        var accumulator = memory.ReadUInt32(stack + 0x20);
        var limit = memory.ReadUInt32(stack + 0x24);
        var index = memory.ReadUInt32(stack + 0x28);
        if (index >= limit || limit > 4096)
        {
            return false;
        }

        var remaining = limit - index;
        if (remaining > (uint.MaxValue / 3u) || table > uint.MaxValue - (remaining * 3u))
        {
            return false;
        }

        var tableBytes = checked((int)(remaining * 3u));
        if (!memory.TryGetSystemRamOffset(table, tableBytes, out _))
        {
            return false;
        }

        var targetByte = memory.ReadByte(stack + 0x2F);
        var targetRegister = unchecked((uint)(sbyte)targetByte);
        var pointer = table;
        var skippedUnmatchedIterations = 0ul;
        var foundMatch = false;
        byte lastAdvance = 0;

        while (index < limit)
        {
            var tableByte = memory.ReadByte(pointer);
            if (tableByte == targetRegister)
            {
                foundMatch = true;
                break;
            }

            lastAdvance = memory.ReadByte(pointer + 2);
            accumulator += lastAdvance;
            pointer += 3;
            index++;
            skippedUnmatchedIterations++;
        }

        skippedInstructions = foundMatch
            ? (skippedUnmatchedIterations * 23) + 11
            : (skippedUnmatchedIterations * 23) + 2;
        if (skippedInstructions == 0 || skippedInstructions > maxInstructionsToSkip)
        {
            skippedInstructions = 0;
            return false;
        }

        memory.WriteUInt32(stack, pointer);
        memory.WriteUInt32(stack + 0x20, accumulator);
        memory.WriteUInt32(stack + 0x28, index);

        if (foundMatch)
        {
            var tableByte = memory.ReadByte(pointer);
            State.R[0] = 47;
            State.R[1] = index;
            State.R[2] = targetRegister;
            State.R[3] = tableByte;
            State.T = true;
        }
        else
        {
            State.R[0] = lastAdvance;
            State.R[1] = limit;
            State.R[2] = limit;
            State.R[3] = limit;
            State.T = true;
        }

        State.Pc = 0x8C00_86DE;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinZeroBitGlyphLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_8A12
            || step.Opcode != 0x891B
            || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal)
            || delayedBranchTarget is not null
            || immediateBranchTarget != 0x8C00_8A4C
            || State.Pc != 0x8C00_8A4C
            || !State.T
            || State.R[3] != 0)
        {
            return false;
        }

        if (memory.ReadInstructionUInt16(0x8C00_89F6) != 0xE01F
            || memory.ReadInstructionUInt16(0x8C00_89F8) != 0x03FC
            || memory.ReadInstructionUInt16(0x8C00_89FA) != 0x633C
            || memory.ReadInstructionUInt16(0x8C00_89FC) != 0x52F5
            || memory.ReadInstructionUInt16(0x8C00_89FE) != 0x622B
            || memory.ReadInstructionUInt16(0x8C00_8A00) != 0x432D
            || memory.ReadInstructionUInt16(0x8C00_8A02) != 0x84F7
            || memory.ReadInstructionUInt16(0x8C00_8A04) != 0x600C
            || memory.ReadInstructionUInt16(0x8C00_8A06) != 0x2309
            || memory.ReadInstructionUInt16(0x8C00_8A08) != 0x1F34
            || memory.ReadInstructionUInt16(0x8C00_8A0A) != 0x60F2
            || memory.ReadInstructionUInt16(0x8C00_8A0C) != 0x8801
            || memory.ReadInstructionUInt16(0x8C00_8A0E) != 0x8B01
            || memory.ReadInstructionUInt16(0x8C00_8A10) != 0x2338
            || memory.ReadInstructionUInt16(0x8C00_8A12) != 0x891B
            || memory.ReadInstructionUInt16(0x8C00_8A4C) != 0x52F2
            || memory.ReadInstructionUInt16(0x8C00_8A4E) != 0x7201
            || memory.ReadInstructionUInt16(0x8C00_8A50) != 0x1F22
            || memory.ReadInstructionUInt16(0x8C00_8A52) != 0x53F8
            || memory.ReadInstructionUInt16(0x8C00_8A54) != 0x8532
            || memory.ReadInstructionUInt16(0x8C00_8A56) != 0x6303
            || memory.ReadInstructionUInt16(0x8C00_8A58) != 0x51F8
            || memory.ReadInstructionUInt16(0x8C00_8A5A) != 0x8513
            || memory.ReadInstructionUInt16(0x8C00_8A5C) != 0x230F
            || memory.ReadInstructionUInt16(0x8C00_8A5E) != 0x001A
            || memory.ReadInstructionUInt16(0x8C00_8A60) != 0x3203
            || memory.ReadInstructionUInt16(0x8C00_8A62) != 0x8B01
            || memory.ReadInstructionUInt16(0x8C00_8A64) != 0xA007
            || memory.ReadInstructionUInt16(0x8C00_8A66) != 0x0009
            || memory.ReadInstructionUInt16(0x8C00_8A68) != 0x53F3
            || memory.ReadInstructionUInt16(0x8C00_8A6A) != 0x52F5
            || memory.ReadInstructionUInt16(0x8C00_8A6C) != 0x3238
            || memory.ReadInstructionUInt16(0x8C00_8A6E) != 0x1F25
            || memory.ReadInstructionUInt16(0x8C00_8A70) != 0x51F5
            || memory.ReadInstructionUInt16(0x8C00_8A72) != 0x4111
            || memory.ReadInstructionUInt16(0x8C00_8A74) != 0x89BF
            || memory.ReadUInt32(0x8C00_8A94) != 0x8C00_98CC
            || memory.ReadUInt32(0x8C00_8A98) != 0x8C00_9A28
            || memory.ReadUInt32(0x8C00_8A9C) != 0x8C00_8AD0)
        {
            return false;
        }

        var stack = State.R[15];
        if (stack is < 0x7E00_0000 or >= 0x7E00_0FE0)
        {
            return false;
        }

        var mode = memory.ReadUInt32(stack);
        var mask = memory.ReadByte(stack + 0x07);
        var stepValue = memory.ReadUInt32(stack + 0x0C);
        var bitResult = memory.ReadUInt32(stack + 0x10);
        var bitCountdown = memory.ReadUInt32(stack + 0x14);
        var currentByte = memory.ReadByte(stack + 0x1F);
        var geometry = memory.ReadUInt32(stack + 0x20);
        if (mode != 1
            || mask != 1
            || stepValue != 1
            || bitResult != 0
            || bitCountdown > 7
            || geometry is < 0x7E00_0000 or >= 0x7E00_0FF8)
        {
            return false;
        }

        var width = (short)memory.ReadUInt16(geometry + 0x04);
        var height = (short)memory.ReadUInt16(geometry + 0x06);
        if (width <= 0 || height <= 0)
        {
            return false;
        }

        var cellLimit = (uint)(width * height);
        var cellIndex = memory.ReadUInt32(stack + 0x08);
        if (cellLimit == 0 || cellIndex >= cellLimit)
        {
            return false;
        }

        var zeroIterations = 0ul;
        var finalCellIndex = cellIndex;
        var finalBitCountdown = bitCountdown;
        while (finalBitCountdown <= 7)
        {
            var shifted = (uint)currentByte >> (int)finalBitCountdown;
            if ((shifted & mask) != 0)
            {
                break;
            }

            var nextCellIndex = finalCellIndex + 1;
            if (nextCellIndex >= cellLimit)
            {
                break;
            }

            zeroIterations++;
            finalCellIndex = nextCellIndex;
            finalBitCountdown--;
        }

        if (zeroIterations == 0)
        {
            return false;
        }

        var skippedBeforeFinalZeroTail = (zeroIterations - 1) * 34;
        skippedInstructions = skippedBeforeFinalZeroTail + 19;
        if (skippedInstructions > maxInstructionsToSkip)
        {
            skippedInstructions = 0;
            return false;
        }

        memory.WriteUInt32(stack + 0x08, finalCellIndex);
        memory.WriteUInt32(stack + 0x14, finalBitCountdown);
        State.R[0] = cellLimit;
        State.R[1] = finalBitCountdown;
        State.R[2] = finalBitCountdown;
        State.R[3] = stepValue;
        State.Macl = cellLimit;
        State.T = finalBitCountdown <= 7;
        State.Pc = State.T ? 0x8C00_89F6 : 0x8C00_8A76;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinGlyphBitDispatch(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
