    internal bool TryFastForwardIpBinSetBitGlyphDrawTail(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        const ulong tailInstructions = 35;

        skippedInstructions = 0;
        if (step.Pc != 0x8C00_8A3E
            || step.Opcode != 0x62F3
            || State.Pc != 0x8C00_8A40
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null
            || maxInstructionsToSkip < tailInstructions)
        {
            return false;
        }

        if (memory.ReadInstructionUInt16(0x8C00_8A3E) != 0x62F3
            || memory.ReadInstructionUInt16(0x8C00_8A40) != 0x7226
            || memory.ReadInstructionUInt16(0x8C00_8A42) != 0x6421
            || memory.ReadInstructionUInt16(0x8C00_8A44) != 0x340C
            || memory.ReadInstructionUInt16(0x8C00_8A46) != 0xD315
            || memory.ReadInstructionUInt16(0x8C00_8A48) != 0x430B
            || memory.ReadInstructionUInt16(0x8C00_8A4A) != 0x0009
            || memory.ReadUInt32(0x8C00_8A9C) != 0x8C00_8AD0
            || !IsIpBinGlyphDrawHelper())
        {
            return false;
        }

        var stack = State.R[15];
        var drawStack = stack - 16;
        if (stack is < 0x7E00_0010 or > 0x7E00_0FF0)
        {
            return false;
        }

        var xBase = (uint)(short)memory.ReadUInt16(stack + 38);
        var xOffset = State.R[0];
        var x = xBase + xOffset;
        var y = State.R[5];
        var color = State.R[6];
        const uint maxY = 479;
        const uint maxX = 639;
        const uint width = maxX + 1;
        const uint framebufferBase = 0x8CED_4000;
        if (x > maxX || y > maxY)
        {
            return false;
        }

        var pixelIndex = ((maxY - y) * width) + (maxX - x);
        var destination = framebufferBase + (pixelIndex * 4);
        if (!memory.TryGetSystemRamOffset(destination, 4, out _))
        {
            return false;
        }

        memory.WriteUInt32(drawStack + 12, x);
        memory.WriteUInt32(drawStack + 8, y);
        memory.WriteUInt32(drawStack + 4, color);
        memory.WriteUInt32(drawStack, destination);
        memory.WriteUInt32(destination, color);

        State.R[0] = x;
        State.R[1] = color;
        State.R[2] = maxX;
        State.R[3] = destination;
        State.R[4] = x;
        State.Pr = 0x8C00_8A4C;
        State.T = false;
        State.Pc = 0x8C00_8A4C;
        State.InstructionsExecuted += tailInstructions;
        skippedInstructions = tailInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    private bool TryFastForwardIpBinGlyphLoopTailFromEntry(
        uint stack,
        uint cellIndex,
        ulong maxInstructionsToSkip,
        out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (!IsIpBinGlyphLoopTail()
            || stack is < 0x7E00_0000 or > 0x7E00_0FD8)
        {
            return false;
        }

        var geometry = memory.ReadUInt32(stack + 0x20);
        if (geometry is < 0x7E00_0000 or > 0x7E00_0FF8)
        {
            return false;
        }

        var width = (short)memory.ReadUInt16(geometry + 0x04);
        var height = (short)memory.ReadUInt16(geometry + 0x06);
        if (width <= 0 || height <= 0)
        {
            return false;
        }

        var cellLimit = (uint)(width * height);
        var nextCellIndex = cellIndex + 1;
        if (cellLimit == 0 || cellIndex >= cellLimit || nextCellIndex > cellLimit)
        {
            return false;
        }

        if (nextCellIndex >= cellLimit)
        {
            skippedInstructions = 14;
            if (maxInstructionsToSkip < skippedInstructions)
            {
                skippedInstructions = 0;
                return false;
            }

            memory.WriteUInt32(stack + 0x08, nextCellIndex);
            State.R[0] = cellLimit;
            State.R[3] = (uint)width;
            State.Macl = cellLimit;
            State.R[1] = geometry;
            State.R[2] = nextCellIndex;
            State.T = true;
            State.Pc = 0x8C00_8A76;
            return true;
        }

        skippedInstructions = 19;
        if (maxInstructionsToSkip < skippedInstructions)
        {
            skippedInstructions = 0;
            return false;
        }

        var stepValue = memory.ReadUInt32(stack + 0x0C);
        if (stepValue == 0)
        {
            skippedInstructions = 0;
            return false;
        }

        var nextBitCountdown = memory.ReadUInt32(stack + 0x14) - stepValue;
        memory.WriteUInt32(stack + 0x08, nextCellIndex);
        memory.WriteUInt32(stack + 0x14, nextBitCountdown);
        State.R[0] = cellLimit;
        State.R[1] = nextBitCountdown;
        State.R[2] = nextBitCountdown;
        State.R[3] = stepValue;
        State.Macl = cellLimit;
        State.T = unchecked((int)nextBitCountdown) >= 0;
        State.Pc = State.T ? 0x8C00_89F6 : 0x8C00_8A76;
        return true;
    }

    private ulong ExecuteIpBinSignedDivideRemainderTail()
    {
        ulong skippedInstructions = 0;
        State.R[15] -= 4;
        memory.WriteUInt32(State.R[15], State.R[2]);
        skippedInstructions++;
        skippedInstructions++;

        State.R[15] -= 4;
        memory.WriteUInt32(State.R[15], State.R[3]);
        skippedInstructions++;
        State.R[2] = 0;
        State.R[15] -= 4;
        memory.WriteUInt32(State.R[15], State.R[4]);
        ExecuteDiv0S(2, 1);
        State.R[4] = State.T ? 1u : 0u;
        ExecuteSubc(3, 3);
        ExecuteSubc(2, 1);
        ExecuteDiv0S(0, 3);
        skippedInstructions += 8;

        for (var index = 0; index < 32; index++)
        {
            ExecuteRotcl(1);
            ExecuteDiv1(0, 3);
            skippedInstructions += 2;
        }

        ExecuteDiv0S(2, 3);
        State.R[2] = State.T ? 1u : 0u;
        State.R[2] ^= State.R[4];
        ExecuteRotcr(2);
        skippedInstructions += 4;

        skippedInstructions++;
        if (State.T)
        {
            ExecuteDiv0S(0, 3);
            State.T = (State.R[3] & 0x1) != 0;
            State.R[3] = (uint)(unchecked((int)State.R[3]) >> 1);
            ExecuteDiv1(0, 3);
            skippedInstructions += 3;
        }

        State.R[3] += State.R[4];
        State.R[0] = State.R[3];
        State.R[4] = memory.ReadUInt32(State.R[15]);
        State.R[15] += 4;
        State.R[3] = memory.ReadUInt32(State.R[15]);
        State.R[15] += 4;
        State.R[2] = memory.ReadUInt32(State.R[15]);
        State.R[15] += 4;
        skippedInstructions += 6;
        return skippedInstructions;
    }

    internal bool TryFastForwardIpBinSignedDivideQuotientHelper(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        const ulong helperTailInstructions = 79;

        skippedInstructions = 0;
        if (step.Pc != 0x8C00_98CC
            || step.Opcode != 0x2008
            || State.Pc != 0x8C00_98CE
            || State.T
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null
            || maxInstructionsToSkip < helperTailInstructions)
        {
            return false;
        }

        if (!IsIpBinSignedDivideQuotientHelper())
        {
            return false;
        }

        var divisor = unchecked((int)State.R[0]);
        var dividend = unchecked((int)State.R[1]);
        var stack = State.R[15];
        if (divisor <= 0
            || dividend < 0
            || stack is < 0x7E00_0008 or > 0x7E00_0FFC)
        {
            return false;
        }

        var quotient = unchecked((uint)(dividend / divisor));
        memory.WriteUInt32(stack - 4, State.R[2]);
        memory.WriteUInt32(stack - 8, State.R[3]);

        State.R[0] = quotient;
        State.R[1] = quotient;
        State.T = false;
        State.Pc = State.Pr;
        State.InstructionsExecuted += helperTailInstructions;
        skippedInstructions = helperTailInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardIpBinSignedDivideRemainderHelper(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C00_9A28
            || step.Opcode != 0x2008
            || State.Pc != 0x8C00_9A2A
            || State.T
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null)
        {
            return false;
        }

        const ulong maxSkippedInstructionCount = 89;
        if (!IsIpBinSignedDivideRemainderHelper()
            || maxInstructionsToSkip < maxSkippedInstructionCount
            || State.R[15] is < 0x7E00_000C or > 0x7E00_0FFC)
        {
            return false;
        }

        skippedInstructions = ExecuteIpBinSignedDivideRemainderTail();
        State.Pc = State.Pr;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
