    internal bool TryFastForwardSonicAdventure2RecordNameParseEntryTail(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C13_4DB4
            || step.Opcode != 0x2FE6
            || State.Pc != 0x8C13_4DB6
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null
            || !IsSonicAdventure2RecordNameParseHelper()
            || State.R[15] < 12
            || !memory.TryGetSystemRamOffset(State.R[15] - 12, 16, out _))
        {
            return false;
        }

        return TryFastForwardSonicAdventure2RecordNameParseCore(
            State.R[4],
            State.R[5],
            State.Pr,
            State.R[12],
            State.R[13],
            memory.ReadUInt32(State.R[15]),
            State.R[15] + 4,
            5,
            maxInstructionsToSkip,
            out skippedInstructions,
            State.R[15]);
    }

    internal bool TryFastForwardSonicAdventure2RecordNameWalkLoopTail(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C13_4EAA
            || step.Opcode != 0x65C3
            || State.Pc != 0x8C13_4EAC
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null
            || !IsSonicAdventure2RecordNameWalkLoopTail()
            || State.R[5] != State.R[12]
            || State.R[15] < 16
            || !memory.TryGetSystemRamOffset(State.R[15] - 16, 28, out _))
        {
            return false;
        }

        var endSource = memory.ReadUInt32(State.R[15] + 8);
        var currentSource = State.R[13];
        var currentDestination = State.R[12];
        var currentIndex = State.R[14];
        var plans = new List<SonicAdventure2RecordNameParsePlan>();
        var skippedInstructionCount = 0UL;
        var firstIteration = true;
        uint terminalPc = 0;
        while (true)
        {
            if (!TryPrepareSonicAdventure2RecordNameParse(
                    currentSource,
                    currentDestination,
                    prologueSkippedInstructionCount: 6,
                    maxInstructionsToSkip: ulong.MaxValue,
                    out var plan))
            {
                if (plans.Count == 0)
                {
                    return false;
                }

                terminalPc = 0x8C13_4EAA;
                break;
            }

            var iterationSkippedInstructions = (firstIteration ? 0UL : 1UL) + 2UL + plan.SkippedInstructions + 3;
            if (plan.FirstByte == 0)
            {
                terminalPc = 0x8C13_4ED2;
                skippedInstructionCount += iterationSkippedInstructions;
                plans.Add(plan);
                break;
            }

            if (currentIndex == 0)
            {
                if (!memory.TryGetSystemRamOffset(currentSource + 10, 4, out _)
                    || memory.ReadUInt32(currentSource + 10) != State.R[11])
                {
                    return false;
                }

                iterationSkippedInstructions += 5;
            }
            else
            {
                iterationSkippedInstructions += 2;
            }

            if (currentSource > uint.MaxValue - plan.FirstByte
                || currentDestination > uint.MaxValue - 44)
            {
                return false;
            }

            var nextSource = currentSource + plan.FirstByte;
            var nextDestination = currentDestination + 44;
            var nextIndex = currentIndex + 1;
            iterationSkippedInstructions += 6;
            if (nextSource >= endSource)
            {
                terminalPc = 0x8C13_4ED2;
                skippedInstructionCount += iterationSkippedInstructions;
                plans.Add(plan);
                break;
            }

            iterationSkippedInstructions += 2;
            if (nextIndex >= State.R[10])
            {
                terminalPc = 0x8C13_4ED2;
                skippedInstructionCount += iterationSkippedInstructions;
                plans.Add(plan);
                break;
            }

            skippedInstructionCount += iterationSkippedInstructions;
            plans.Add(plan);
            currentSource = nextSource;
            currentDestination = nextDestination;
            currentIndex = nextIndex;
            firstIteration = false;

            if (skippedInstructionCount > maxInstructionsToSkip)
            {
                return false;
            }
        }

        if (plans.Count == 0
            || terminalPc == 0
            || skippedInstructionCount > maxInstructionsToSkip)
        {
            return false;
        }

        currentSource = State.R[13];
        currentDestination = State.R[12];
        currentIndex = State.R[14];
        firstIteration = true;
        foreach (var plan in plans)
        {
            if (!firstIteration)
            {
                State.R[5] = currentDestination;
            }

            memory.WriteUInt32(State.R[15] - 4, currentIndex);
            memory.WriteUInt32(State.R[15] - 8, currentSource);
            memory.WriteUInt32(State.R[15] - 12, currentDestination);
            memory.WriteUInt32(State.R[15] - 16, 0x8C13_4EB0);
            ApplySonicAdventure2RecordNameParsePlan(plan, 0x8C13_4EB0, currentDestination, currentSource, currentIndex, State.R[15]);

            State.R[4] = plan.FirstByte;
            if (plan.FirstByte == 0)
            {
                State.T = true;
                State.Pc = terminalPc;
                break;
            }

            if (currentIndex == 0)
            {
                State.R[2] = memory.ReadUInt32(currentDestination + 4);
                State.T = State.R[2] == State.R[11];
            }

            State.R[2] = endSource;
            State.R[13] = unchecked(State.R[13] + State.R[4]);
            State.R[12] = unchecked(State.R[12] + 44);
            State.T = State.R[13] >= State.R[2];
            State.R[14]++;
            if (State.T)
            {
                State.Pc = terminalPc;
                break;
            }

            State.T = State.R[14] >= State.R[10];
            State.Pc = State.T ? terminalPc : 0x8C13_4EAA;
            currentSource = State.R[13];
            currentDestination = State.R[12];
            currentIndex = State.R[14];
            firstIteration = false;
        }

        State.InstructionsExecuted += skippedInstructionCount;
        skippedInstructions = skippedInstructionCount;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    private bool TryFastForwardSonicAdventure2RecordNameParseCore(
        uint source,
        uint destination,
        uint savedPr,
        uint savedR12,
        uint savedR13,
        uint savedR14,
        uint finalStackPointer,
        ulong prologueSkippedInstructionCount,
        ulong maxInstructionsToSkip,
        out ulong skippedInstructions,
        uint? prologueTailStackPointer = null)
    {
        skippedInstructions = 0;
        if (!TryPrepareSonicAdventure2RecordNameParse(source, destination, prologueSkippedInstructionCount, maxInstructionsToSkip, out var plan))
        {
            return false;
        }

        if (prologueTailStackPointer is not null)
        {
            var stackPointer = prologueTailStackPointer.Value;
            memory.WriteUInt32(stackPointer - 4, savedR13);
            memory.WriteUInt32(stackPointer - 8, savedR12);
            memory.WriteUInt32(stackPointer - 12, savedPr);
        }

        ApplySonicAdventure2RecordNameParsePlan(plan, savedPr, savedR12, savedR13, savedR14, finalStackPointer);
        State.InstructionsExecuted += plan.SkippedInstructions;
        skippedInstructions = plan.SkippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    private bool TryPrepareSonicAdventure2RecordNameParse(
        uint source,
        uint destination,
        ulong prologueSkippedInstructionCount,
        ulong maxInstructionsToSkip,
        out SonicAdventure2RecordNameParsePlan plan)
    {
        plan = default;
        if (!memory.TryGetSystemRamOffset(source, 34, out _))
        {
            return false;
        }

        var firstByte = memory.ReadByte(source);
        var flags = memory.ReadByte(source + 25);
        var nameLength = memory.ReadByte(source + 32);
        var flagsIncludeFullName = (flags & 0x02) != 0;
        var copiedNameLength = flagsIncludeFullName ? nameLength : nameLength - 2u;
        if (firstByte < 34
            || (!flagsIncludeFullName && nameLength < 3)
            || copiedNameLength == 0
            || !memory.TryGetSystemRamOffset(source + 33, (int)copiedNameLength, out _))
        {
            return false;
        }

        var name = new byte[copiedNameLength];
        for (var offset = 0u; offset < copiedNameLength; offset++)
        {
            name[offset] = memory.ReadByte(source + 33 + offset);
        }

        byte[] hashedName;
        ulong skippedInstructionCount;
        if (flagsIncludeFullName && name[0] == 0)
        {
            if (copiedNameLength != 1)
            {
                return false;
            }

            hashedName = [(byte)'.'];
            skippedInstructionCount = 159;
        }
        else if (flagsIncludeFullName && name[0] == 1)
        {
            if (copiedNameLength != 1)
            {
                return false;
            }

            hashedName = [(byte)'.', (byte)'.'];
            skippedInstructionCount = 176;
        }
        else
        {
            hashedName = name;
            skippedInstructionCount = flagsIncludeFullName
                ? 145UL + (13UL * copiedNameLength)
                : 134UL + (19UL * copiedNameLength);
        }

        skippedInstructionCount += prologueSkippedInstructionCount;
        if (maxInstructionsToSkip < skippedInstructionCount
            || !TryComputeSonicAdventure2StringHash(hashedName, out var hash)
            || !memory.TryGetSystemRamOffset(destination, 10 + hashedName.Length + 1, out _))
        {
            return false;
        }

        plan = new SonicAdventure2RecordNameParsePlan(
            source,
            destination,
            firstByte,
            flags,
            copiedNameLength,
            name,
            hashedName,
            hash,
            skippedInstructionCount);
        return true;
    }

    private void ApplySonicAdventure2RecordNameParsePlan(
        SonicAdventure2RecordNameParsePlan plan,
        uint savedPr,
        uint savedR12,
        uint savedR13,
        uint savedR14,
        uint finalStackPointer)
    {
        memory.Write(plan.Destination, [
            memory.ReadByte(plan.Source + 2),
            memory.ReadByte(plan.Source + 3),
            memory.ReadByte(plan.Source + 4),
            memory.ReadByte(plan.Source + 5)]);
        memory.Write(plan.Destination + 4, [
            memory.ReadByte(plan.Source + 10),
            memory.ReadByte(plan.Source + 11),
            memory.ReadByte(plan.Source + 12),
            memory.ReadByte(plan.Source + 13)]);
        memory.Write(plan.Destination + 8, [plan.Flags]);
        memory.Write(plan.Destination + 10, plan.Name);
        memory.Write(plan.Destination + 10 + plan.CopiedNameLength, [0]);
        memory.Write(plan.Destination + 10, plan.HashedName);
        memory.Write(plan.Destination + 10 + (uint)plan.HashedName.Length, [0]);
        memory.Write(plan.Destination + 9, [(byte)plan.Hash.Result]);

        State.R[0] = plan.FirstByte;
        State.R[2] = 0;
        State.R[3] = 97;
        State.R[4] = plan.Hash.LastByte;
        State.R[5] = plan.Hash.LastByte;
        State.R[6] = 0;
        State.R[7] = plan.Source + 33 + plan.CopiedNameLength;
        State.R[12] = savedR12;
        State.R[13] = savedR13;
        State.R[14] = savedR14;
        State.R[15] = finalStackPointer;
        State.Pr = savedPr;
        State.Pc = savedPr;
        State.T = true;
    }

    private readonly record struct SonicAdventure2RecordNameParsePlan(
        uint Source,
        uint Destination,
        uint FirstByte,
        byte Flags,
        uint CopiedNameLength,
        byte[] Name,
        byte[] HashedName,
        SonicAdventure2StringHashResult Hash,
        ulong SkippedInstructions);

    private static bool TryComputeSonicAdventure2StringHash(ReadOnlySpan<byte> source, out SonicAdventure2StringHashResult result)
    {
        result = default;
        if (source.IsEmpty)
        {
            return false;
        }

        uint accumulator = 0xDA;
        foreach (var value in source)
        {
            if (value == 0
                || value >= (byte)'a')
            {
                return false;
            }

            accumulator = unchecked(accumulator + value);
        }

        result = new SonicAdventure2StringHashResult(source[0], source[^1], (accumulator >> 2) & 0xFF, 0);
        return true;
    }

    internal bool TryFastForwardSonicAdventure2RecordHashScan(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C13_4F74
            || step.Opcode != 0x8FE3
            || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal)
            || delayedBranchTarget != 0x8C13_4F3E
            || State.Pc != 0x8C13_4F76)
        {
            return false;
        }

        if (!IsSonicAdventure2RecordHashScan()
            || State.R[13] >= State.R[11]
            || State.R[14] > uint.MaxValue - 44
            || maxInstructionsToSkip < 10)
        {
            return false;
        }

        const uint recordStride = 44;
        const ulong instructionsPerNonmatch = 9;
        var target = State.R[10] & 0xFF;
        var recordAddress = State.R[14] + recordStride;
        var scannedRecords = State.R[13];
        var maxIterations = Math.Min((ulong)(State.R[11] - scannedRecords), (maxInstructionsToSkip - 1) / instructionsPerNonmatch);
        uint lastValue = 0;
        var iterationsToSkip = 0UL;
        while (iterationsToSkip < maxIterations)
        {
            if (recordAddress > uint.MaxValue - 9
                || !memory.TryGetSystemRamOffset(recordAddress + 9, 1, out _))
            {
                return false;
            }

            var value = memory.ReadByte(recordAddress + 9);
            if (value == target)
            {
                break;
            }

            var nextIndex = scannedRecords + (uint)iterationsToSkip + 1;
            if (nextIndex >= State.R[11])
            {
                break;
            }

            lastValue = value;
            iterationsToSkip++;
            if (recordAddress > uint.MaxValue - recordStride)
            {
                return false;
            }

            recordAddress += recordStride;
        }

        if (iterationsToSkip == 0)
        {
            return false;
        }

        State.R[0] = lastValue;
        State.R[3] = target;
        State.R[13] += (uint)iterationsToSkip;
        State.R[14] += ((uint)iterationsToSkip + 1) * recordStride;
        State.T = false;
        State.Pc = 0x8C13_4F3E;
        skippedInstructions = 1 + (iterationsToSkip * instructionsPerNonmatch);
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    internal bool TryFastForwardSonicAdventure2RecordCompactionLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C13_5E16
            || step.Opcode != 0x8FE7
            || !step.Trace.EndsWith(" ; taken", StringComparison.Ordinal)
            || delayedBranchTarget != 0x8C13_5DE8
            || State.Pc != 0x8C13_5E18)
        {
            return false;
        }

        const uint recordCount = 24;
        if (!IsSonicAdventure2RecordCompactionLoop()
            || State.R[7] != recordCount
            || State.R[6] == 0
            || State.R[6] >= recordCount)
        {
            return false;
        }

        var remainingRecords = recordCount - State.R[6];
        var skippedInstructionCount = 1UL + ((ulong)remainingRecords * 25);
        if (maxInstructionsToSkip < skippedInstructionCount)
        {
            return false;
        }

        var source = State.R[4] + 44;
        var destination = State.R[5];
        var sourceBytes = checked((int)(((remainingRecords - 1) * 44) + 24));
        var destinationBytes = checked((int)remainingRecords * 24);
        if (State.R[4] > uint.MaxValue - 44
            || !memory.TryGetSystemRamOffset(source, sourceBytes, out _)
            || !memory.TryGetSystemRamOffset(destination, destinationBytes, out _))
        {
            return false;
        }

        for (var index = 0u; index < remainingRecords; index++)
        {
            var recordSource = source + (index * 44);
            var recordDestination = destination + (index * 24);
            memory.WriteUInt32(recordDestination, memory.ReadUInt32(recordSource));
            memory.WriteUInt32(recordDestination + 4, memory.ReadUInt32(recordSource + 8));
            memory.WriteUInt32(recordDestination + 8, memory.ReadUInt32(recordSource + 16));
            memory.WriteUInt32(recordDestination + 12, memory.ReadUInt32(recordSource + 20));
        }

        var lastSource = source + ((remainingRecords - 1) * 44);
        State.R[0] = (uint)(sbyte)memory.ReadByte(lastSource + 11);
        State.R[2] = (uint)(sbyte)memory.ReadByte(lastSource);
        State.R[3] = memory.ReadUInt32(lastSource + 20);
        State.R[4] += (25 - State.R[6]) * 44;
        State.R[5] += remainingRecords * 24;
        State.R[6] = recordCount;
        State.T = true;
        State.Pc = 0x8C13_5E1A;
        State.InstructionsExecuted += skippedInstructionCount;
        skippedInstructions = skippedInstructionCount;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

