        const ulong scalarPathInstructions = 16;
        if (maxInstructionsToSkip < scalarPathInstructions
            || !IsSonicAdventure2G2PioWriteLoop()
            || State.R[9] == 0
            || (State.R[9] & 0x8000_0000) != 0
            || !memory.TryGetSystemRamOffset(State.R[15], 20, out _))
        {
            return false;
        }

        var index = memory.ReadUInt32(State.R[15]);
        var destination = memory.ReadUInt32(State.R[15] + 4);
        var source = State.R[3];
        var storedSource = memory.ReadUInt32(State.R[15] + 8);
        var sourceStride = memory.ReadUInt32(State.R[15] + 12);
        var destinationStride = memory.ReadUInt32(State.R[15] + 16);
        if (index >= State.R[9]
            || source != storedSource
            || destinationStride == 0
            || destinationStride > 4
            || sourceStride > 4
            || !IsAicaRamAddress(destination, 4)
            || !CanReadContiguousWordRange(source, 4))
        {
            return false;
        }

        var value = memory.ReadUInt32(source);
        WriteSonicAdventure2G2PioWord(destination, value);
        var completedSource = unchecked(source + sourceStride);
        var completedDestination = unchecked(destination + destinationStride);
        var completedIndex = index + 1;
        memory.WriteUInt32(State.R[15], completedIndex);
        memory.WriteUInt32(State.R[15] + 4, completedDestination);
        memory.WriteUInt32(State.R[15] + 8, completedSource);
        State.R[0] = completedDestination;
        State.R[1] = completedSource;
        State.R[2] = destinationStride;
        State.R[3] = completedIndex;
        State.T = completedIndex >= State.R[9];
        State.Pc = State.T ? 0x8C13_5C16 : 0x8C13_5BDA;
        State.InstructionsExecuted += scalarPathInstructions;
        skippedInstructions = scalarPathInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;

        if (!State.T
            && maxInstructionsToSkip > skippedInstructions)
        {
            var loopStep = new Sh4StepResult(0x8C13_5C14, 0x2F32, string.Empty);
            if (TryFastForwardSonicAdventure2G2PioWriteLoop(loopStep, maxInstructionsToSkip - skippedInstructions, out var chainedSkippedInstructions))
            {
                skippedInstructions += chainedSkippedInstructions;
            }
        }

        return true;
    }

    internal bool TryFastForwardSonicAdventure2G2PioWriteLoopEntryTail(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C13_5BC0
            || step.Opcode != 0x62F2
            || State.Pc != 0x8C13_5BC2
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null)
        {
            return false;
        }

        const ulong firstIterationSkippedInstructions = 106;
        if (maxInstructionsToSkip < firstIterationSkippedInstructions
            || !IsSonicAdventure2G2PioWriteLoopEntryTail()
            || State.R[9] == 0
            || (State.R[9] & 0x8000_0000) != 0
            || State.R[10] != 0x8C15_AF98
            || State.R[11] != 0x8C15_B244
            || State.R[13] != 0x1FFF_FFFF
            || State.R[14] != 0x0070_0000
            || !memory.TryGetSystemRamOffset(State.R[15], 24, out _))
        {
            return false;
        }

        var stack = State.R[15];
        var destination = State.R[2];
        var source = memory.ReadUInt32(stack + 20);
        var sourceStride = unchecked(memory.ReadUInt32(stack + 16) << 2);
        var destinationStride = unchecked(State.R[8] << 2);
        var maskedDestination = destination & State.R[13];
        if (destinationStride == 0
            || destinationStride > 4
            || sourceStride > 4
            || source > uint.MaxValue - sourceStride
            || destination > uint.MaxValue - destinationStride
            || maskedDestination < State.R[14]
            || maskedDestination > 0x0100_0000
            || !IsAicaRamAddress(destination, 4)
            || !CanReadContiguousWordRange(source, 4))
        {
            return false;
        }

        memory.WriteUInt32(stack + 4, destination);
        memory.WriteUInt32(stack + 8, source);
        memory.WriteUInt32(stack, 0);
        memory.WriteUInt32(stack + 12, sourceStride);
        memory.WriteUInt32(stack + 16, destinationStride);
        WriteSonicAdventure2G2PioWord(destination, memory.ReadUInt32(source));

        var completedDestination = destination + destinationStride;
        var completedSource = source + sourceStride;
        memory.WriteUInt32(stack, 1);
        memory.WriteUInt32(stack + 4, completedDestination);
        memory.WriteUInt32(stack + 8, completedSource);
        State.R[0] = completedDestination;
        State.R[1] = completedSource;
        State.R[2] = destinationStride;
        State.R[3] = 1;
        State.R[8] = maskedDestination;
        State.Pr = 0x8C13_5BF4;
        State.T = State.R[9] <= 1;
        State.Pc = State.T ? 0x8C13_5C16 : 0x8C13_5BDA;
        State.InstructionsExecuted += firstIterationSkippedInstructions;
        skippedInstructions = firstIterationSkippedInstructions;

        if (!State.T
            && maxInstructionsToSkip > skippedInstructions)
        {
            var loopStep = new Sh4StepResult(0x8C13_5C14, 0x2F32, string.Empty);
            if (TryFastForwardSonicAdventure2G2PioWriteLoop(loopStep, maxInstructionsToSkip - skippedInstructions, out var chainedSkippedInstructions))
            {
                skippedInstructions += chainedSkippedInstructions;
            }
        }

        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    private void WriteSonicAdventure2G2PioWord(uint destination, uint value)
    {
        if (!memory.TryWriteAicaRamDriverField(destination, value))
        {
            memory.WriteUInt32(destination, value);
        }
    }

    internal bool TryFastForwardSonicAdventure2CacheInvalidateLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C10_F446
            || step.Opcode != 0x7420
            || State.Pc != 0x8C10_F440
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null)
        {
            return false;
        }

        if (!IsSonicAdventure2CacheInvalidateLoop()
            || State.R[5] == 0
            || State.T)
        {
            return false;
        }

        const ulong instructionsPerIteration = 4;
        var iterationsToSkip = Math.Min((ulong)State.R[5], maxInstructionsToSkip / instructionsPerIteration);
        if (iterationsToSkip == 0
            || iterationsToSkip > uint.MaxValue / 32
            || State.R[4] > uint.MaxValue - ((uint)iterationsToSkip * 32))
        {
            return false;
        }

        skippedInstructions = iterationsToSkip * instructionsPerIteration;
        State.R[5] -= (uint)iterationsToSkip;
        State.R[4] += (uint)iterationsToSkip * 32;
        var completed = State.R[5] == 0;
        State.T = completed;
        State.Pc = completed ? 0x8C10_F448 : 0x8C10_F440;
        State.InstructionsExecuted += skippedInstructions;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    private bool IsSonicAdventure2CacheInvalidateLoop() =>
        memory.ReadInstructionUInt16(0x8C10_F440) == 0x0493
        && memory.ReadInstructionUInt16(0x8C10_F442) == 0x4510
        && memory.ReadInstructionUInt16(0x8C10_F444) == 0x8FFC
        && memory.ReadInstructionUInt16(0x8C10_F446) == 0x7420
        && memory.ReadInstructionUInt16(0x8C10_F448) == 0xD207
        && memory.ReadUInt32(0x8C10_F468) == 0x8C10_F638;

    internal bool TryFastForwardSonicAdventure2CacheWritebackLoop(Sh4StepResult step, ulong maxInstructionsToSkip, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        if (step.Pc != 0x8C10_F8E0
            || step.Opcode != 0x04B3
            || State.Pc != 0x8C10_F8E2
            || delayedBranchTarget is not null
            || immediateBranchTarget is not null)
        {
            return false;
        }

        var remainingIterations = State.R[5];
        if (remainingIterations == 0
            || !IsSonicAdventure2CacheWritebackLoop()
            || !TryGetSonicAdventure2CacheLineSpan(State.R[4], remainingIterations, out _))
        {
            return false;
        }

        var skippedInstructionCount = ((ulong)remainingIterations - 1UL) * 4UL + 3UL;
        if (maxInstructionsToSkip < skippedInstructionCount)
        {
            return false;
        }

        State.R[4] += remainingIterations * 32u;
        State.R[5] = 0;
        State.T = true;
        State.Pc = 0x8C10_F8E8;
        State.InstructionsExecuted += skippedInstructionCount;
        skippedInstructions = skippedInstructionCount;
        delayedBranchTarget = null;
        immediateBranchTarget = null;
        return true;
    }

    private bool TryGetSonicAdventure2CacheLineSpan(uint address, uint iterations, out int byteCount)
    {
        byteCount = 0;
        var spanBytes = ((ulong)iterations - 1UL) * 32UL + 1UL;
        if (spanBytes > int.MaxValue
            || (ulong)address + ((ulong)iterations * 32UL) > uint.MaxValue
            || address > uint.MaxValue - (uint)(spanBytes - 1UL))
        {
            return false;
        }

        byteCount = (int)spanBytes;
        return memory.TryGetSystemRamOffset(address, byteCount, out _);
    }

    private bool IsSonicAdventure2CacheWritebackLoop() =>
        memory.ReadInstructionUInt16(0x8C10_F8D8) == 0x751F
        && memory.ReadInstructionUInt16(0x8C10_F8DA) == 0x4509
        && memory.ReadInstructionUInt16(0x8C10_F8DC) == 0x4509
        && memory.ReadInstructionUInt16(0x8C10_F8DE) == 0x4501
        && memory.ReadInstructionUInt16(0x8C10_F8E0) == 0x04B3
        && memory.ReadInstructionUInt16(0x8C10_F8E2) == 0x4510
        && memory.ReadInstructionUInt16(0x8C10_F8E4) == 0x8FFC
        && memory.ReadInstructionUInt16(0x8C10_F8E6) == 0x7420
        && memory.ReadInstructionUInt16(0x8C10_F8E8) == 0xD207
