        {
            return false;
        }

        uint mask;
        uint targetPc;
        switch (step.Pc)
        {
            case 0x8C15_C55C when step.Opcode == 0x6433 && State.Pc == 0x8C15_C55E:
                skippedInstructions = 3;
                mask = State.R[4] & 0xFF;
                if (State.R[2] != 31 || State.R[3] != State.R[4])
