                State.T = mask == 0;
                targetPc = State.T ? 0x8C15_C572u : 0x8C15_C564u;
                break;

            case 0x8C15_C55E when step.Opcode == 0x614C && State.Pc == 0x8C15_C560:
                skippedInstructions = 2;
                mask = State.R[1];
                if ((mask & 0xFFFF_FF00) != 0 || State.R[4] != mask)
