    private static bool IsAicaRamAddress(uint address, int length)
    {
        var physical = DreamcastMemory.TranslateAddress(address);
        return physical >= 0x0080_0000
            && physical <= 0x00A0_0000 - (uint)length;
    }

    private static bool IsAicaRegisterAddress(uint address, int length)
    {
        var physical = DreamcastMemory.NormalizePhysicalAddress(DreamcastMemory.TranslateAddress(address));
        return physical >= 0x0070_0000
            && physical <= 0x0071_000C - (uint)length;
    }

    private static bool CanFastForwardG2PioReadWordSource(uint address, int length) =>
        IsAicaRamAddress(address, length)
        || IsAicaRegisterAddress(address, length);

    private static bool IsExpansionProbeAddress(uint address, int length)
    {
        var physical = DreamcastMemory.NormalizePhysicalAddress(DreamcastMemory.TranslateAddress(address));
        return physical is >= 0x0060_0000 and < 0x0060_0800
                && physical <= 0x0060_0800 - (uint)length
            || physical is >= 0x0100_0000 and < 0x0200_0000
                && physical <= 0x0200_0000 - (uint)length
            || physical is >= 0x1400_0000 and < 0x1800_0000
                && physical <= 0x1800_0000 - (uint)length;
    }

    private bool CanReadContiguousWordRange(uint address, int length) =>
        memory.TryGetSystemRamOffset(address, length, out _)
        || IsAicaRamAddress(address, length)
        || memory.TryGetPvrVramOffset(address, length, out _);

    private bool CanReadSystemOrAicaRamWord(uint address) =>
        memory.TryGetSystemRamOffset(address, 4, out _)
        || IsAicaRamAddress(address, 4);

    private void IncrementSystemRamWord(uint address)
    {
        if (memory.TryGetSystemRamOffset(address, 4, out _))
        {
            memory.WriteUInt32(address, memory.ReadUInt32(address) + 1);
        }
    }

    private static bool TryComputeSkippedInstructions(uint remainingIterations, uint bodyInstructionCount, out ulong skippedInstructions)
    {
        skippedInstructions = 0;
        var perIteration = (ulong)bodyInstructionCount + 2;
        if (perIteration != 0 && remainingIterations > (ulong.MaxValue - 1) / perIteration)
        {
            return false;
        }

        skippedInstructions = 1 + ((ulong)remainingIterations * perIteration);
        return true;
    }

